		ObjectNode b = ownerNode();
		b.put("firstName", first); b.put("lastName", last); b.put("postcode", "2001");
		int id = createOwnerOk(b);
		getOwner(id).andExpect(jsonPath("$.namesakeCount").value(1));
	}
}

